const fs = require('fs');

const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;
const N = tokens[idx++];
const M = tokens[idx++];

const adj = Array.from({ length: N + 1 }, () => []);
for (let i = 0; i < M; i++) {
  const a = tokens[idx++];
  const b = tokens[idx++];
  const c = tokens[idx++];
  adj[a].push([b, c]);
  adj[b].push([a, c]);
}

// Dijkstra com min-heap binário -> O((N + M) log N)
const heap = [];

function heapPush(item) {
  heap.push(item);
  let i = heap.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (heap[p][0] <= heap[i][0]) break;
    const t = heap[p]; heap[p] = heap[i]; heap[i] = t;
    i = p;
  }
}

function heapPop() {
  const top = heap[0];
  const last = heap.pop();
  const size = heap.length;
  if (size > 0) {
    heap[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1;
      const r = 2 * i + 2;
      let s = i;
      if (l < size && heap[l][0] < heap[s][0]) s = l;
      if (r < size && heap[r][0] < heap[s][0]) s = r;
      if (s === i) break;
      const t = heap[i]; heap[i] = heap[s]; heap[s] = t;
      i = s;
    }
  }
  return top;
}

const dist = new Array(N + 1).fill(Infinity);
dist[1] = 0;
heapPush([0, 1]);

while (heap.length > 0) {
  const [d, u] = heapPop();
  if (d > dist[u]) continue; // entrada obsoleta no heap
  if (u === N) break;        // primeira extração válida do destino -> distância final
  for (const [v, w] of adj[u]) {
    const nd = d + w;
    if (nd < dist[v]) {
      dist[v] = nd;
      heapPush([nd, v]);
    }
  }
}

